14	/// Same plain (non-mocktail) fake shape as
15	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
16	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
17	/// real stream the cubit (built from this fake, not mocked) actually
18	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
19	/// a `Stream.multi` replay wrapper (unlike the production repository) —
20	/// `AccountSettingsCubit`'s own constructor already reads
21	/// [currentBiometricEnabled] directly for its initial state, so no replay
22	/// machinery is needed for a fake with exactly one subscriber.
23	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
24	  bool _value = true;
25	  final _controller = StreamController<bool>.broadcast();
26	
27	  /// The next `setBiometricEnabled()` call's own result — defaults to a
28	  /// failure so a test must opt in to the success path explicitly, same
29	  /// convention as the cubit-level fake.
30	  Either<Failure, Unit> setBiometricEnabledResult = left(
31	    const Failure.malformedResponse(message: 'fake: not configured'),
32	  );
33	
34	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
35	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
36	  /// disable itself while a toggle is in flight).
37	  Completer<void>? setBiometricEnabledGate;
38	
39	  @override
40	  bool get currentBiometricEnabled => _value;
41	
42	  @override
43	  Stream<bool> get biometricEnabledStream => _controller.stream;
44	
45	  @override
46	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
47	
48	  @override
49	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
50	    final gate = setBiometricEnabledGate;
51	    if (gate != null) {
52	      await gate.future;
53	    }
54	    final previous = _value;
55	    _emit(enabled);
56	    final result = setBiometricEnabledResult;
57	    if (result.isLeft()) {
58	      _emit(previous);
59	    }
60	    return result;
61	  }
62	
63	  @override
64	  Future<void> dispose() => _controller.close();
65	
66	  void _emit(bool value) {
67	    _value = value;
68	    _controller.add(value);
69	  }
70	}
71	
72	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
73	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
74	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
75	/// rather than a bare `MaterialApp`.
76	GoRouter _routerWith(Widget screen) {
77	  return GoRouter(
78	    initialLocation: '/configuracoes',
79	    routes: [
80	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
81	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
82	    ],
83	  );
84	}
85	
86	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
87	/// pair and pumps the real screen around it, registering both for cleanup.
88	///
89	/// Deliberately constructed *inside* each `testWidgets` body (via this
90	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
91	/// `package:test`'s own per-test zone, a different zone than the one
92	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
93	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
94	/// subscription to the repository's stream, set up in its constructor)
95	/// created in that outer zone does not reliably get its pending events
96	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
97	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
98	/// widget never rebuilt, no matter how many `pump()` calls followed.
99	/// Constructing the cubit here, inside the same zone `tester.pump()`
100	/// drains, avoids the mismatch entirely.
101	Future<(
102	  _FakeAccountSettingsRepository,
103	  AccountSettingsCubit,
104	)>
105	_pumpScreen(WidgetTester tester) async {
106	  final fakeRepository = _FakeAccountSettingsRepository();
107	  final cubit = AccountSettingsCubit(fakeRepository);
108	  addTearDown(() => cubit.close());
109	  addTearDown(fakeRepository.dispose);
110	
111	  final router = _routerWith(AccountSettingsScreen(cubit: cubit));
112	  addTearDown(router.dispose);
113	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
114	
115	  return (fakeRepository, cubit);
116	}
117	
118	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
119	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
120	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
121	/// toggle's error message renders inline — `app_router_test.dart` already
122	/// proves the screen is *reachable*; this suite proves its own rendering
123	/// and interaction in isolation.
124	void main() {
125	  testWidgets(
126	    'shows the header titled Configurações and exactly one switch — no '
127	    'other content (AC: "shows only the biometric toggle")',
128	    (tester) async {
129	      await _pumpScreen(tester);
130	
131	      expect(find.byType(BackArrowHeader), findsOneWidget);
132	      expect(find.text('Configurações'), findsOneWidget);
133	      expect(find.byType(Switch), findsOneWidget);
134	      expect(find.text('Entrar com biometria'), findsOneWidget);
135	    },
136	  );
137	
138	  testWidgets(
139	    'the switch mirrors currentBiometricEnabled (true) at construction',
140	    (tester) async {
141	      await _pumpScreen(tester);
142	
143	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
144	      expect(switchWidget.value, isTrue);
145	    },
146	  );
147	
148	  testWidgets(
149	    'a false currentBiometricEnabled (already fetched before the screen '
150	    'opened) renders the switch off',
151	    (tester) async {
152	      final fakeRepository = _FakeAccountSettingsRepository().._emit(false);
153	      final cubit = AccountSettingsCubit(fakeRepository);
154	      addTearDown(() => cubit.close());
155	      addTearDown(fakeRepository.dispose);
156	
157	      final router = _routerWith(AccountSettingsScreen(cubit: cubit));
158	      addTearDown(router.dispose);
159	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
160	
161	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
162	      expect(switchWidget.value, isFalse);
163	    },
164	  );
165	
166	  testWidgets(
167	    'tapping the switch calls toggleBiometric() with the requested value and '
168	    'flips the rendered switch — no error band on success',
169	    (tester) async {
170	      final (fakeRepository, _) = await _pumpScreen(tester);
171	      fakeRepository.setBiometricEnabledResult = right(unit);
172	
173	      await tester.tap(find.byType(Switch));
174	      await tester.pumpAndSettle();
175	
176	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
177	      expect(switchWidget.value, isFalse);
178	      // No error text rendered — only the label and the back-arrow title.
179	      expect(find.textContaining('conexão'), findsNothing);
180	    },
181	  );
182	
183	  testWidgets(
184	    'a failed toggle reverts the switch and shows the Failure\'s message '
185	    'inline, below the toggle row',
186	    (tester) async {
187	      final (fakeRepository, _) = await _pumpScreen(tester);
188	      fakeRepository.setBiometricEnabledResult = left(
189	        const Failure.networkTimeout(message: 'Sem conexão'),
190	      );
191	
192	      await tester.tap(find.byType(Switch));
193	      await tester.pumpAndSettle();
194	
195	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
196	      expect(switchWidget.value, isTrue);
197	      expect(find.text('Sem conexão'), findsOneWidget);
198	    },
199	  );
200	
201	  testWidgets(
202	    'the switch disables itself while a toggle is in flight, so a '
203	    'double-tap can never start a second, overlapping call (review '
204	    'finding)',
205	    (tester) async {
206	      final (fakeRepository, _) = await _pumpScreen(tester);
207	      fakeRepository.setBiometricEnabledResult = right(unit);
208	      fakeRepository.setBiometricEnabledGate = Completer<void>();
209	
210	      await tester.tap(find.byType(Switch));
211	      await tester.pump();
212	
213	      var switchWidget = tester.widget<Switch>(find.byType(Switch));
214	      expect(switchWidget.onChanged, isNull);
215	
216	      fakeRepository.setBiometricEnabledGate!.complete();
217	      await tester.pumpAndSettle();
218	
219	      switchWidget = tester.widget<Switch>(find.byType(Switch));
220	      expect(switchWidget.onChanged, isNotNull);
221	      expect(switchWidget.value, isFalse);
222	    },
223	  );
224	
225	  testWidgets(
226	    'a stale error from a previous visit is cleared when the screen '
227	    '(re)mounts — AccountSettingsCubit is a DI singleton that outlives any '
228	    'single visit, so a failed toggle\'s message must not still be '
229	    'showing on a later, unrelated visit (review finding)',
230	    (tester) async {
231	      final (fakeRepository, cubit) = await _pumpScreen(tester);
232	      fakeRepository.setBiometricEnabledResult = left(
233	        const Failure.networkTimeout(message: 'Sem conexão'),
234	      );
235	
236	      await tester.tap(find.byType(Switch));
237	      await tester.pumpAndSettle();
238	      expect(find.text('Sem conexão'), findsOneWidget);
239	
240	      // Simulates leaving and returning to Configurações: a brand new
241	      // `AccountSettingsScreen` (and its own `State`, calling `initState`
242	      // again) built around the SAME, still-singleton cubit — exactly
243	      // what a fresh `GoRoute.builder` call would produce.
244	      final router = _routerWith(AccountSettingsScreen(cubit: cubit));
245	      addTearDown(router.dispose);
246	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
247	
248	      expect(find.text('Sem conexão'), findsNothing);
249	      // The toggle's own confirmed value is untouched by the error clear.
250	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
251	      expect(switchWidget.value, isTrue);
252	    },
253	  );
254	
255	  testWidgets(
256	    'the back arrow navigates to / (shared BackArrowHeader behavior)',
257	    (tester) async {
258	      await _pumpScreen(tester);
259	
260	      await tester.tap(find.byIcon(Icons.chevron_left));
261	      await tester.pumpAndSettle();
262	
263	      expect(find.text('Home'), findsOneWidget);
264	    },
265	  );
266	}
