10	/// The `entries` Hive box's name — the first `hive_ce` box in the app
11	/// (Code Map). A raw `Box<Map>`, not a generated `HiveObject`/
12	/// `TypeAdapter` (Design Notes: avoids adapter codegen for a box nothing
13	/// reads yet).
14	const entriesBoxName = 'entries';
15	
16	/// Registers the `entries` feature into the project's single `get_it`
17	/// instance (`sl`) — mirrors `features/account/account_injection.dart`'s
18	/// pattern. Called from `setupCoreDependencies()` right after
19	/// `Hive.initFlutter()` (Code Map), which must already have run by the
20	/// time this opens its box.
21	Future<void> registerEntriesFeature() async {
22	  final entriesBox = await Hive.openBox<Map>(entriesBoxName);
23	  sl.registerSingleton<Box<Map>>(entriesBox);
24	
25	  sl.registerLazySingleton<EntriesRemoteDataSource>(
26	    () => EntriesRemoteDataSource(sl<ApiClient>()),
27	  );
28	
29	  sl.registerLazySingleton<EntriesRepository>(
30	    () => EntriesRepositoryImpl(
31	      remoteDataSource: sl<EntriesRemoteDataSource>(),
32	      entriesBox: sl<Box<Map>>(),
33	    ),
34	  );
35	
36	  // spec-4-1 — `MeusRegistrosCubit` is a `lazySingleton`, not a factory
37	  // (Code Map/Boundaries), like `AccountSettingsCubit`: long-lived, so
38	  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle,
39	  // same convention `account_injection.dart` already uses.
40	  sl.registerLazySingleton<MeusRegistrosCubit>(
41	    () => MeusRegistrosCubit(sl<EntriesRepository>()),
42	    dispose: (cubit) => cubit.close(),
43	  );
44	}
