6	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
7	/// (no use-case layer, matching this codebase's existing small-scope
8	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
9	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
10	/// the already-fetched pages survive leaving and re-entering
11	/// `/meus-registros` within the same app session.
12	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
13	  MeusRegistrosCubit(this._repository) : super(const MeusRegistrosLoading());
14	
15	  final EntriesRepository _repository;
16	
17	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
18	  /// re-fetches from scratch rather than keeping a previous visit's page
19	  /// around, since a new entry may have been saved (Insertion Modal, Epic
20	  /// 3) since the last visit.
21	  Future<void> loadFirstPage() async {
22	    emit(const MeusRegistrosLoading());
23	    final result = await _repository.list();
24	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
25	    // can race this awaited call (e.g. a fast app teardown mid-request) —
26	    // `emit()` after `close()` would otherwise throw.
27	    if (isClosed) {
28	      return;
29	    }
30	    result.match(
31	      (failure) => emit(MeusRegistrosError(message: failure.message)),
32	      (page) {
33	        if (page.items.isEmpty) {
34	          emit(const MeusRegistrosEmpty());
35	          return;
36	        }
37	        emit(
38	          MeusRegistrosLoaded(
39	            entries: page.items,
40	            nextCursor: page.nextCursor,
41	          ),
42	        );
43	      },
44	    );
45	  }
46	
47	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
48	  /// end. A no-op while not [MeusRegistrosLoaded], while
49	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, or while a call
50	  /// is already in flight — no concurrent overlapping pages, same
51	  /// single-flight intent `AccountSettingsCubit.toggleBiometric`'s own
52	  /// `Switch`-disable achieves through the UI layer instead.
53	  Future<void> loadMore() async {
54	    final current = state;
55	    if (current is! MeusRegistrosLoaded ||
56	        current.nextCursor == null ||
57	        current.isLoadingMore) {
58	      return;
59	    }
60	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
61	    final result = await _repository.list(cursor: current.nextCursor);
62	    if (isClosed) {
63	      return;
64	    }
65	    // Re-reads `state` rather than closing over `current` — defensive
66	    // against `loadFirstPage()` having reset the state to something other
67	    // than `MeusRegistrosLoaded` while this await was pending.
68	    final latest = state;
69	    if (latest is! MeusRegistrosLoaded) {
70	      return;
71	    }
72	    result.match(
73	      (failure) =>
74	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
75	      (page) {
76	        // I/O matrix: "Next page appended, no dup ids" — defensive
77	        // de-duplication in case a cursor-boundary entry is ever repeated
78	        // by the server.
79	        final existingIds = latest.entries.map((entry) => entry.id).toSet();
80	        final newEntries = page.items.where(
81	          (entry) => !existingIds.contains(entry.id),
82	        );
